code_example:
std::vector<int> v = {1, 2, 3};

std::vector<int>::iterator it = v.begin();

// This is always allowed: converting iterator -> const_iterator
std::vector<int>::const_iterator cit = it; 

cit = v.cbegin(); // Assume C++11 for cbegin for demonstration

// This is never allowed and will not compile
// std::vector<int>::iterator it2 = cit; // Error: no implicit conversion

// Even explicit casts are not portable or guaranteed to work
// std::vector<int>::iterator it3 = static_cast<decltype(it)>(cit); // Error
